var e=JSON.parse(`[{"id":"wld-bo-luc-lac","name":"Bò lúc lắc, bœuf secoué au cresson","description":"Cubes de bœuf saisis à feu très vif dans une marinade soja-nuoc-mâm-ail, « secoués » dans la poêle et servis sur cresson, tomates et oignon rouge, avec riz et sauce citron vert-poivre.","emoji":"🥩","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"thai-vietnamienne","prepTime":15,"cookTime":12,"restTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"boeuf-steak","qty":420,"unit":"g","note":"faux-filet ou rumsteck, en cubes de 3 cm"},{"id":"sauce-soja","qty":2,"unit":"cas"},{"id":"sauce-poisson","qty":1,"unit":"cas"},{"id":"miel","qty":1,"unit":"cac"},{"id":"ail","qty":4,"unit":"gousse","note":"hachées"},{"id":"beurre","qty":20,"unit":"g"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"oignon-rouge","qty":1,"unit":"piece","note":"en pétales"},{"id":"mache","qty":100,"unit":"g","note":"cresson"},{"id":"tomate","qty":2,"unit":"piece","note":"en rondelles"},{"id":"citron-vert","qty":1,"unit":"piece"},{"id":"poivre","qty":1,"unit":"cac","note":"fraîchement concassé"},{"id":"riz-blanc","qty":160,"unit":"g","note":"jasmin"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Mélangez le bœuf avec la sauce soja, la sauce poisson, le miel et la moitié de l'ail. Laissez mariner 20 min. Lancez le riz.","Préparez la sauce de trempage : jus du citron vert, 1/2 cac de poivre concassé et une pincée de sel dans deux coupelles.","Disposez le cresson et les tomates sur les assiettes.","Faites chauffer la graisse dans une poêle en fonte à feu très vif jusqu'à ce qu'elle fume. Déposez les cubes en une couche, laissez saisir 1 min 30 sans toucher, puis secouez la poêle et laissez encore 1 min : les faces doivent être brunes et le cœur rosé.","Ajoutez le beurre, le reste d'ail et l'oignon rouge, secouez 1 min jusqu'à ce que le beurre mousse et que l'oignon soit à peine tendre.","Versez le bœuf et ses jus brûlants sur le cresson, poivrez et servez avec le riz et la sauce citron vert à côté."],"tags":["rapide","riche en protéines","une poêle","sportif","prise de masse"],"seasons":[],"technique":"poele","flavors":["umami","acidule","piquant"],"tips":"Le jus chaud de la viande fait légèrement tomber le cresson : c'est voulu, il sert d'assaisonnement."},{"id":"wld-pad-kra-pao-dinde","name":"Pad kra pao de dinde, œuf frit croustillant","description":"Dinde hachée au couteau sautée au wok avec ail, piment et basilic thaï, servie sur riz jasmin avec un œuf frit à bords dentelés.","emoji":"🌿","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"thai-vietnamienne","prepTime":10,"cookTime":12,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"dinde-hachee","qty":400,"unit":"g","note":"idéalement hachée au couteau, cuisse"},{"id":"ail","qty":5,"unit":"gousse"},{"id":"piment-frais","qty":3,"unit":"piece","note":"piments oiseau"},{"id":"haricots-verts","qty":150,"unit":"g","note":"en tronçons de 2 cm"},{"id":"sauce-poisson","qty":2,"unit":"cas"},{"id":"sauce-soja","qty":1,"unit":"cas"},{"id":"miel","qty":1,"unit":"cac"},{"id":"basilic","qty":30,"unit":"g","note":"basilic sacré ou thaï"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"huile-coco","qty":3,"unit":"cas"},{"id":"riz-blanc","qty":170,"unit":"g","note":"jasmin"},{"id":"citron-vert","qty":1,"unit":"piece","optional":true}],"steps":["Lancez le riz. Pilez l'ail et les piments au mortier en pâte grossière (ou hachez-les finement).","Faites frire les œufs : chauffez 2 cas d'huile de coco dans le wok à feu vif, cassez un œuf et arrosez-le d'huile chaude 1 min 30 jusqu'à ce que les bords soient bruns et croustillants et le jaune encore coulant. Réservez, faites le second.","Avec le reste d'huile à feu vif, faites sauter la pâte ail-piment 20 secondes, sans la laisser brûler.","Ajoutez la dinde et faites-la sauter 4 min en l'émiettant jusqu'à ce qu'elle soit bien dorée. Ajoutez les haricots verts et 2 cas d'eau, sautez 2 min.","Versez sauce poisson, sauce soja et miel, mélangez 1 min, puis coupez le feu et incorporez le basilic qui doit juste flétrir.","Servez sur le riz, chaque assiette couronnée d'un œuf frit."],"tags":["rapide","riche en protéines","une poêle","économique","sportif"],"seasons":[],"technique":"wok","flavors":["piquant","herbace","umami"],"tips":"Classiquement au porc ou au poulet ; la dinde de cuisse reste juteuse et change agréablement."},{"id":"wld-curry-vert-crevettes","name":"Curry vert thaï aux crevettes et aubergine","description":"Crevettes pochées dans un curry vert au lait de coco, citronnelle et basilic thaï, avec aubergine et haricots verts, servi sur riz jasmin.","emoji":"🍛","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"thai-vietnamienne","prepTime":10,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"crevette","qty":400,"unit":"g","note":"décortiquées crues, queue laissée"},{"id":"pate-curry","qty":2,"unit":"cas","note":"pâte de curry vert thaïe (sans additifs)"},{"id":"lait-coco","qty":330,"unit":"ml"},{"id":"aubergine","qty":1,"unit":"piece","note":"en cubes de 2 cm"},{"id":"haricots-verts","qty":120,"unit":"g"},{"id":"citronnelle","qty":1,"unit":"piece","note":"écrasée, + 3 feuilles de kaffir"},{"id":"sauce-poisson","qty":2,"unit":"cas"},{"id":"sucre","qty":1,"unit":"cac","note":"sucre de palme ou complet"},{"id":"basilic","qty":20,"unit":"g","note":"basilic thaï"},{"id":"citron-vert","qty":1,"unit":"piece"},{"id":"piment-frais","qty":1,"unit":"piece","optional":true},{"id":"riz-blanc","qty":160,"unit":"g","note":"jasmin"}],"steps":["Lancez le riz. Dans une sauteuse, faites chauffer 4 cas de la crème épaisse du dessus du lait de coco à feu moyen 2 min jusqu'à ce qu'elle frémisse et que le gras perle.","Ajoutez la pâte de curry et faites-la frire 2 min en remuant : elle doit embaumer.","Versez le reste du lait de coco et 100 ml d'eau, ajoutez citronnelle, aubergine, sauce poisson et sucre. Laissez mijoter 10 min à feu doux : l'aubergine doit être fondante.","Ajoutez les haricots verts 3 min, puis les crevettes : 3 min à frémissement, jusqu'à ce qu'elles soient roses et recourbées en C.","Hors du feu, ajoutez le basilic et le jus d'un demi-citron vert. Goûtez : salé (nuoc-mâm), légèrement sucré, piquant. Servez sur le riz avec le piment émincé."],"tags":["rapide","riche en protéines","sans gluten","réconfortant","une poêle"],"seasons":["ete","automne"],"technique":"mijote","flavors":["epice","cremeux","herbace"],"tips":"Ne faites jamais bouillir fort les crevettes : 3 min suffisent, au-delà elles se rétractent."},{"id":"wld-larb-canard","name":"Larb de canard aux herbes et riz grillé","description":"Salade tiède d'Isan : magret haché au couteau, saisi puis relevé de citron vert, nuoc-mâm, échalotes, menthe, coriandre et poudre de riz grillé, avec riz gluant et crudités.","emoji":"🦆","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"thai-vietnamienne","prepTime":20,"cookTime":15,"difficulty":"facile","servings":2,"ingredients":[{"id":"canard-magret","qty":450,"unit":"g","note":"dont la moitié de la peau retirée, hachés au couteau"},{"id":"riz-rond","qty":170,"unit":"g","note":"riz gluant, dont 2 cas pour la poudre grillée"},{"id":"sauce-poisson","qty":3,"unit":"cas"},{"id":"citron-vert","qty":3,"unit":"piece"},{"id":"echalote","qty":3,"unit":"piece","note":"en fines lamelles"},{"id":"menthe","qty":20,"unit":"g"},{"id":"coriandre","qty":20,"unit":"g"},{"id":"oignon-nouveau","qty":3,"unit":"piece"},{"id":"piment-espelette","qty":1,"unit":"cac","note":"piment séché en flocons"},{"id":"concombre","qty":0.5,"unit":"piece","note":"en bâtonnets"},{"id":"laitue","qty":120,"unit":"g","note":"feuilles"},{"id":"haricots-verts","qty":100,"unit":"g","note":"blanchis 2 min"}],"steps":["Faites tremper le riz gluant 4 h (ou la nuit), puis cuisez-le 25 min à la vapeur. Pour gagner du temps, utilisez du riz rond cuit à l'eau.","Poudre de riz grillé : faites dorer 2 cas de riz cru dans une poêle sèche à feu moyen 5 à 6 min en remuant, jusqu'à une couleur noisette, puis pilez-le en poudre grossière.","Faites fondre la peau du magret coupée en petits dés 4 min dans une poêle à feu moyen. Ajoutez la chair hachée et faites-la saisir 3 à 4 min en l'émiettant : elle doit rester rosée par endroits.","Hors du feu, ajoutez immédiatement la sauce poisson, le jus des citrons verts, le piment et les échalotes : mélangez, l'acidité « cuit » légèrement les échalotes.","Ajoutez menthe, coriandre et ciboule ciselées et 1 cas de poudre de riz. Goûtez : le larb doit être franchement acide, salé et piquant.","Servez tiède, saupoudré du reste de poudre de riz, avec le riz gluant, la laitue, le concombre et les haricots verts."],"tags":["riche en protéines","sans gluten","léger","lunch box","sportif"],"seasons":["printemps","ete"],"technique":"poele","flavors":["acidule","herbace","piquant"],"tips":"La poudre de riz grillé se garde 2 semaines en bocal : faites-en d'avance pour toutes vos salades thaïes."},{"id":"wld-carnitas-tortillas","name":"Carnitas, porc confit à l'orange en tacos","description":"Échine de porc confite doucement au saindoux avec orange, ail et épices, puis effilochée et rôtie jusqu'à croustiller, servie en tacos de maïs avec guacamole, oignon et coriandre.","emoji":"🌮","category":"mijote","mealTypes":["diner","dejeuner"],"cuisine":"mexicaine","prepTime":25,"cookTime":180,"difficulty":"facile","servings":4,"ingredients":[{"id":"porc-echine","qty":950,"unit":"g","note":"en cubes de 5 cm"},{"id":"graisse-canard","qty":30,"unit":"g","note":"saindoux"},{"id":"orange","qty":1,"unit":"piece","note":"jus et écorce"},{"id":"citron-vert","qty":3,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece","note":"moitié en quartiers, moitié ciselée"},{"id":"ail","qty":6,"unit":"gousse"},{"id":"cumin","qty":1,"unit":"cac"},{"id":"origan","qty":1,"unit":"cac","note":"origan mexicain"},{"id":"cannelle","qty":1,"unit":"pincee"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"lait","qty":100,"unit":"ml","note":"il aide à caraméliser"},{"id":"tortilla-mais","qty":12,"unit":"piece"},{"id":"avocat","qty":1,"unit":"piece"},{"id":"coriandre","qty":20,"unit":"g"},{"id":"radis","qty":100,"unit":"g","note":"en rondelles"},{"id":"piment-frais","qty":1,"unit":"piece","note":"jalapeño"},{"id":"sel","qty":1,"unit":"cac"}],"steps":["Salez le porc. Dans une cocotte en fonte, faites fondre le saindoux à feu moyen, ajoutez la viande, le jus d'orange et l'écorce, l'oignon en quartiers, l'ail entier, cumin, origan, cannelle, laurier, le lait et 200 ml d'eau.","Portez à frémissement, couvrez et laissez confire 2 h 30 à feu très doux (ou au four à 150 °C), en remuant toutes les 45 min : la viande doit s'effilocher sous la fourchette.","Retirez le couvercle, montez à feu moyen-vif et laissez évaporer le liquide 15 à 20 min : la viande finit par frire dans sa graisse et doit dorer et croustiller sur les bords. Effilochez grossièrement.","Guacamole : écrasez l'avocat avec le jus d'un citron vert, un peu d'oignon ciselé, de coriandre et de sel.","Chauffez les tortillas 30 secondes par face dans une poêle sèche très chaude, gardez-les dans un torchon.","Garnissez chaque tortilla de carnitas, guacamole, oignon ciselé, coriandre, radis et jalapeño, avec un quartier de citron vert."],"tags":["week-end","mijoté","familial","batch cooking","sans gluten","calorique"],"seasons":[],"technique":"mijote","flavors":["fruite","acidule","reconfortant"],"tips":"Les restes se réchauffent à la poêle très chaude : ils recroustillent parfaitement. Congélation 3 mois."},{"id":"wld-pollo-mole","name":"Pollo con mole, sauce mole simplifiée","description":"Cuisses de poulet mijotées dans un mole maison aux piments doux, tomates, sésame, amandes, raisins secs et une touche de chocolat noir, servies avec riz et tortillas.","emoji":"🍗","category":"mijote","mealTypes":["diner","dejeuner"],"cuisine":"mexicaine","prepTime":30,"cookTime":70,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":4,"unit":"piece"},{"id":"paprika","qty":2,"unit":"cas","note":"ou 4 piments ancho/guajillo réhydratés"},{"id":"piment-espelette","qty":1,"unit":"cac","note":"piment chipotle"},{"id":"tomate","qty":3,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"sesame","qty":25,"unit":"g","note":"+ un peu pour servir"},{"id":"amande","qty":30,"unit":"g"},{"id":"raisins-secs","qty":30,"unit":"g"},{"id":"chocolat-noir","qty":30,"unit":"g","note":"70 %"},{"id":"cannelle","qty":1,"unit":"cac"},{"id":"girofle","qty":1,"unit":"pincee","note":"clou de girofle moulu"},{"id":"cumin","qty":1,"unit":"cac"},{"id":"bouillon-volaille","qty":500,"unit":"ml"},{"id":"graisse-canard","qty":2,"unit":"cas","note":"saindoux"},{"id":"riz-blanc","qty":200,"unit":"g"},{"id":"tortilla-mais","qty":8,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"yaourt-nature","qty":500,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Salez les cuisses. Dans une cocotte, faites-les dorer dans le saindoux à feu moyen-vif 5 min par face, peau d'abord. Réservez.","Dans la même cocotte à feu moyen, faites dorer sésame et amandes 2 min, puis oignon et ail 4 min, puis tomates coupées et raisins secs 5 min, jusqu'à ce que les tomates s'effondrent.","Ajoutez paprika, chipotle, cannelle, girofle et cumin, mélangez 30 secondes, puis versez 300 ml de bouillon. Mixez le tout très finement au mixeur plongeant.","Remettez la sauce à feu doux, ajoutez le chocolat haché et le reste du bouillon. Remuez jusqu'à ce que le chocolat fonde : la sauce doit être brun-rouge, veloutée et napper la cuillère.","Remettez les cuisses, couvrez et laissez mijoter 40 min à feu doux en remuant de temps en temps (la sauce attache facilement). Lancez le riz 20 min avant la fin.","Servez les cuisses nappées de mole, parsemées de sésame grillé, avec le riz et les tortillas chaudes.","Prévoyez un yaourt nature entier en dessert (son calcium limite l’absorption des oxalates)."],"tags":["week-end","mijoté","familial","sans gluten","réconfortant"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["epice","umami","fruite"],"tips":"Le mole est meilleur le lendemain. Doublez la sauce et congelez-la : elle accompagne aussi la dinde."},{"id":"wld-lomo-saltado","name":"Lomo saltado péruvien","description":"Le sauté sino-péruvien : lanières de bœuf, oignon rouge, tomates et piment flambés au wok avec soja et vinaigre, mélangés à des frites dorées au beurre clarifié, avec un peu de riz.","emoji":"🍟","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"latino-americaine","prepTime":15,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"boeuf-steak","qty":420,"unit":"g","note":"rumsteck ou filet, en lanières de 1 cm"},{"id":"pomme-de-terre","qty":450,"unit":"g","note":"en frites de 1 cm"},{"id":"beurre-clarifie","qty":3,"unit":"cas"},{"id":"oignon-rouge","qty":1,"unit":"piece","note":"en gros pétales"},{"id":"tomate","qty":2,"unit":"piece","note":"en quartiers épépinés"},{"id":"piment-frais","qty":1,"unit":"piece","note":"ají amarillo ou piment jaune, en lanières"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"sauce-soja","qty":3,"unit":"cas"},{"id":"vinaigre-cidre","qty":1,"unit":"cas","note":"vinaigre de vin rouge"},{"id":"cumin","qty":0.5,"unit":"cac"},{"id":"coriandre","qty":15,"unit":"g"},{"id":"riz-blanc","qty":100,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Lancez le riz. Préchauffez le four à 220 °C. Rincez et séchez les frites, enrobez-les de 2 cas de beurre clarifié fondu, salez et étalez-les sur une plaque. Enfournez 25 à 30 min en les retournant à mi-cuisson, jusqu'à ce qu'elles soient dorées et croustillantes.","Assaisonnez le bœuf de sel, poivre, cumin et ail haché.","Chauffez le reste de beurre clarifié dans un wok à feu très vif jusqu'à ce qu'il fume. Saisissez le bœuf en deux fournées, 1 min 30 chacune : bien bruni, encore rosé. Réservez.","Dans le wok toujours très chaud, faites sauter l'oignon rouge et le piment 1 min : ils doivent rester croquants. Ajoutez les tomates 30 secondes.","Remettez le bœuf, versez soja et vinaigre le long de la paroi (ça doit grésiller et fumer), mélangez 30 secondes, ajoutez la coriandre.","Mélangez les frites au dernier moment pour qu'elles s'imprègnent du jus sans ramollir, et servez avec une petite part de riz."],"tags":["riche en protéines","prise de masse","four","calorique","familial"],"seasons":["ete","automne"],"technique":"wok","flavors":["umami","acidule","piquant"],"tips":"Les frites au four restent croustillantes plus longtemps dans la sauce que des frites cuites à l'eau."},{"id":"wld-picanha-farofa","name":"Picanha grillée, farofa et feijão","description":"Aiguillette de rumsteck avec sa couche de gras, grillée au gros sel à la brésilienne, servie avec une farofa croustillante au beurre et lardons, haricots noirs et vinagrete de tomates.","emoji":"🔥","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"latino-americaine","prepTime":25,"cookTime":35,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-steak","qty":1000,"unit":"g","note":"picanha (aiguillette de rumsteck) avec son gras"},{"id":"sel","qty":1,"unit":"cas","note":"gros sel"},{"id":"manioc","qty":200,"unit":"g","note":"farine de manioc (farinha) pour la farofa"},{"id":"beurre","qty":50,"unit":"g"},{"id":"lardons","qty":100,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece","note":"ciselé"},{"id":"haricots-noirs","qty":400,"unit":"g","note":"cuits"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"tomate","qty":3,"unit":"piece","note":"en petits dés"},{"id":"oignon-rouge","qty":1,"unit":"piece","note":"en petits dés"},{"id":"poivron-rouge","qty":0.5,"unit":"piece","note":"en petits dés"},{"id":"persil","qty":15,"unit":"g"},{"id":"vinaigre-cidre","qty":2,"unit":"cas"},{"id":"huile-olive","qty":2,"unit":"cas"}],"steps":["Sortez la picanha 1 h avant. Quadrillez le gras sans entailler la chair, puis coupez-la en 4 steaks épais dans le sens de la largeur. Frottez-les généreusement de gros sel.","Vinagrete : mélangez tomates, oignon rouge, poivron, persil, vinaigre, huile d'olive et une pincée de sel. Laissez macérer au frais.","Feijão : faites revenir l'ail et la moitié des lardons 3 min, ajoutez les haricots noirs, le laurier et 150 ml d'eau ; laissez épaissir 15 min à feu doux en écrasant un quart des haricots.","Farofa : faites fondre le beurre avec le reste des lardons 4 min, ajoutez l'oignon 4 min, puis la farine de manioc ; remuez 5 à 6 min à feu moyen jusqu'à ce qu'elle soit blonde et sente la noisette.","Grillez la picanha au barbecue ou dans une poêle-gril très chaude, d'abord côté gras 5 min pour le faire fondre et dorer, puis 3 à 4 min par face (55 °C à cœur pour saignant). Laissez reposer 5 min.","Tranchez finement, gras compris, et servez avec la farofa, le feijão et la vinagrete."],"tags":["barbecue","week-end","riche en protéines","familial","prise de masse","sans gluten"],"seasons":["printemps","ete"],"technique":"grill","flavors":["grille","umami","acidule"],"tips":"Demandez la picanha à votre boucher sous le nom « aiguillette baronne » ou « pointe de culotte »."},{"id":"wld-ceviche-bar-patate-douce","name":"Ceviche de bar, patate douce et maïs","description":"Bar cru « cuit » quelques minutes dans un leche de tigre citron vert-piment-gingembre, avec oignon rouge croquant, coriandre, patate douce fondante, maïs grillé et avocat.","emoji":"🍋","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"latino-americaine","prepTime":25,"cookTime":25,"difficulty":"facile","servings":2,"ingredients":[{"id":"bar","qty":420,"unit":"g","note":"filets sans peau ultra-frais (ou dorade, corvina)"},{"id":"citron-vert","qty":6,"unit":"piece"},{"id":"piment-frais","qty":1,"unit":"piece","note":"ají ou piment jaune, épépiné"},{"id":"gingembre","qty":10,"unit":"g"},{"id":"ail","qty":1,"unit":"gousse"},{"id":"oignon-rouge","qty":1,"unit":"piece","note":"en lamelles très fines"},{"id":"coriandre","qty":20,"unit":"g"},{"id":"patate-douce","qty":2,"unit":"piece"},{"id":"mais","qty":200,"unit":"g","note":"grains d'un épi ou de choclo"},{"id":"avocat","qty":1,"unit":"piece"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"sel","qty":1,"unit":"cac"},{"id":"yaourt-nature","qty":250,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Sécurité : congelez le poisson au moins 24 h à −20 °C avant de le préparer cru (ou achetez-le « qualité sashimi », déjà assaini) — recommandation ANSES contre les parasites.","Cuisez les patates douces entières 25 min dans l'eau frémissante (la lame d'un couteau doit entrer sans résistance), laissez-les tiédir puis coupez-les en rondelles épaisses. Faites griller le maïs 5 min dans une poêle sèche très chaude.","Plongez l'oignon rouge 10 min dans de l'eau glacée salée pour l'adoucir, égouttez.","Leche de tigre : mixez ou pilez le jus des citrons verts avec le gingembre, l'ail, la moitié du piment, quelques tiges de coriandre, le sel et 2 petits cubes de poisson. Filtrez.","Coupez le bar bien froid en cubes de 2 cm, salez-le, versez le leche de tigre et mélangez délicatement. Laissez « cuire » 5 à 8 min au frais : l'extérieur blanchit, le cœur reste translucide.","Ajoutez l'oignon rouge, le reste du piment émincé et la coriandre, un filet d'huile d'olive.","Servez aussitôt dans des assiettes creuses avec la patate douce, le maïs et l'avocat en tranches, arrosé du jus du ceviche.","Prévoyez un yaourt nature entier en dessert (son calcium limite l’absorption des oxalates)."],"tags":["léger","riche en protéines","repas froid","sans gluten","sportif"],"seasons":["printemps","ete"],"technique":"cru","flavors":["acidule","frais","iode"],"tips":"Le ceviche se mange tout de suite : au-delà de 15 min dans le citron, le poisson devient farineux."},{"id":"wld-anticuchos-coeur","name":"Anticuchos de cœur de bœuf, papas doradas","description":"Brochettes péruviennes de cœur de bœuf marinées au vinaigre, ail, cumin et piment panca, grillées et servies avec pommes de terre rissolées, maïs et sauce verte au piment.","emoji":"🍢","category":"plat","mealTypes":["diner"],"cuisine":"latino-americaine","prepTime":25,"cookTime":30,"restTime":240,"difficulty":"facile","servings":2,"ingredients":[{"id":"coeur-boeuf","qty":500,"unit":"g","note":"paré (sans gras ni nerfs), en cubes de 3 cm"},{"id":"vinaigre-cidre","qty":60,"unit":"ml","note":"vinaigre de vin rouge"},{"id":"ail","qty":5,"unit":"gousse"},{"id":"cumin","qty":1,"unit":"cac"},{"id":"paprika","qty":2,"unit":"cac","note":"ou pâte d'ají panca"},{"id":"origan","qty":1,"unit":"cac"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"pomme-de-terre","qty":550,"unit":"g","note":"grenailles"},{"id":"beurre-clarifie","qty":1,"unit":"cas"},{"id":"mais","qty":250,"unit":"g","note":"1 gros épi en tronçons"},{"id":"piment-frais","qty":1,"unit":"piece","note":"piment vert"},{"id":"coriandre","qty":20,"unit":"g"},{"id":"citron-vert","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Mélangez vinaigre, ail écrasé, cumin, paprika, origan, 2 cas d'huile d'olive et 1 cac de sel. Ajoutez le cœur et laissez mariner 4 h au frais (jusqu'à une nuit).","Cuisez les grenailles 12 min à l'eau salée, égouttez, écrasez-les légèrement et faites-les rissoler 10 min dans le beurre clarifié à feu moyen-vif jusqu'à ce qu'elles soient dorées. Cuisez le maïs 8 min à l'eau bouillante.","Sauce verte : mixez la coriandre, le piment, le jus du citron vert, 1 cas d'huile d'olive, 2 cas d'eau et une pincée de sel.","Enfilez le cœur sur des piques (4 à 5 cubes chacune). Gardez la marinade.","Grillez sur un barbecue très chaud ou une poêle-gril fumante 2 min par face (8 min en tout) en badigeonnant de marinade : le cœur doit être bien marqué et rosé à cœur, jamais trop cuit sous peine de durcir.","Servez aussitôt avec les pommes de terre, le maïs et la sauce verte."],"tags":["abats","barbecue","riche en protéines","économique","sans gluten"],"seasons":["ete","automne"],"technique":"grill","flavors":["grille","epice","acidule"],"tips":"Le cœur est un muscle très maigre et riche en CoQ10 : il se traite comme un steak, saisi vite et rosé."},{"id":"wld-kottbullar-puree-airelles","name":"Köttbullar, purée et airelles","description":"Boulettes suédoises bœuf-porc au quatre-épices, dorées au beurre et nappées d'une sauce crème au jus, avec purée beurrée, airelles et concombre mariné.","emoji":"🧆","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"nordique","prepTime":30,"cookTime":30,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-hache","qty":400,"unit":"g"},{"id":"porc-hache","qty":300,"unit":"g"},{"id":"panure","qty":40,"unit":"g"},{"id":"lait","qty":250,"unit":"ml","note":"100 ml pour les boulettes, 150 ml pour la purée"},{"id":"oignon","qty":1,"unit":"piece","note":"très finement haché"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"girofle","qty":0.5,"unit":"cac","note":"quatre-épices"},{"id":"beurre","qty":60,"unit":"g"},{"id":"farine","qty":1,"unit":"cas"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"creme-liquide","qty":120,"unit":"ml"},{"id":"sauce-soja","qty":1,"unit":"cac"},{"id":"pomme-de-terre-farineuse","qty":1000,"unit":"g"},{"id":"airelles","qty":80,"unit":"g","note":"airelles (lingonberries)"},{"id":"concombre","qty":1,"unit":"piece","note":"pour le pressgurka"},{"id":"vinaigre-cidre","qty":3,"unit":"cas"},{"id":"persil","qty":10,"unit":"g","optional":true},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout","note":"poivre blanc"}],"steps":["Pressgurka : tranchez le concombre très finement, mélangez avec le vinaigre, 1 cas d'eau et une pincée de sel. Réservez au frais.","Faites gonfler la chapelure 5 min dans 100 ml de lait. Ajoutez les deux viandes, l'oignon, l'œuf, le quatre-épices, 1 cac de sel et du poivre. Mélangez sans trop travailler et formez des boulettes de 3 cm avec les mains mouillées.","Cuisez les pommes de terre épluchées en morceaux 20 min à l'eau salée. Égouttez, écrasez avec 30 g de beurre et 150 ml de lait chaud jusqu'à une purée lisse.","Dans une grande poêle, faites dorer les boulettes dans 30 g de beurre à feu moyen en deux fournées, 8 à 10 min en les roulant : elles doivent être brunes de partout et fermes au toucher. Réservez.","Dans la même poêle, sans rajouter de beurre, ajoutez la farine 1 min, puis le bouillon en fouettant en raclant les sucs. Laissez épaissir 3 min, ajoutez la crème et la sauce soja, puis remettez les boulettes 3 min à frémissement.","Servez boulettes et sauce avec la purée, une cuillerée d'airelles et le concombre mariné."],"tags":["familial","réconfortant","batch cooking","calorique","riche en protéines"],"seasons":["automne","hiver"],"technique":"poele","flavors":["cremeux","reconfortant","fruite"],"tips":"Les boulettes crues se congèlent à plat sur une plaque, puis en sachet : cuisson directe à la poêle, 2 min de plus."},{"id":"wld-truite-aneth-hovmastarsas","name":"Truite rôtie à l'aneth, pommes de terre nouvelles et sauce hovmästar","description":"Filets de truite rôtis au beurre et à l'aneth, pommes de terre nouvelles et sauce suédoise moutarde-miel-aneth, celle qui accompagne le gravlax.","emoji":"🐟","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"nordique","prepTime":10,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"truite","qty":420,"unit":"g","note":"filets avec la peau (ou omble)"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"nouvelles, non épluchées"},{"id":"beurre","qty":30,"unit":"g"},{"id":"aneth","qty":20,"unit":"g"},{"id":"moutarde","qty":2,"unit":"cas","note":"dont 1 de moutarde douce"},{"id":"miel","qty":1,"unit":"cas"},{"id":"vinaigre-cidre","qty":1,"unit":"cas"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"citron","qty":1,"unit":"piece"},{"id":"concombre","qty":0.5,"unit":"piece","note":"en rubans"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Cuisez les pommes de terre nouvelles 18 à 20 min dans l'eau salée avec quelques tiges d'aneth : la pointe d'un couteau doit s'y enfoncer sans résistance.","Sauce hovmästar : fouettez moutarde, miel et vinaigre, puis ajoutez l'huile en filet en fouettant jusqu'à une sauce épaisse et brillante. Ajoutez la moitié de l'aneth ciselé, sel et poivre.","Posez les filets peau dessous dans un plat beurré, parsemez de noisettes de beurre, d'aneth et de zeste de citron, salez.","Enfournez 10 à 12 min : la chair doit être rose pâle, juste opaque et se détacher en lamelles.","Égouttez les pommes de terre, roulez-les dans le beurre fondu de la truite et le reste d'aneth.","Servez avec la sauce, les rubans de concombre arrosés d'un trait de citron."],"tags":["rapide","four","riche en protéines","léger","familial"],"seasons":["printemps","ete"],"technique":"four","flavors":["herbace","frais","acidule"],"tips":"Même recette avec un saumon gravlax tranché épais, poêlé 30 secondes par face."},{"id":"wld-fiskefrikadeller-remoulade","name":"Fiskefrikadeller, galettes de poisson danoises et rémoulade","description":"Galettes moelleuses de cabillaud haché à l'aneth, dorées au beurre, servies avec pommes de terre persillées, carottes et une rémoulade maison aux cornichons et câpres.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"nordique","prepTime":25,"cookTime":25,"restTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"cabillaud","qty":480,"unit":"g","note":"ou lieu, sans peau ni arêtes"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"farine","qty":30,"unit":"g"},{"id":"creme-liquide","qty":50,"unit":"ml"},{"id":"oignon","qty":0.5,"unit":"piece","note":"râpé"},{"id":"aneth","qty":15,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"beurre","qty":35,"unit":"g"},{"id":"pomme-de-terre","qty":550,"unit":"g"},{"id":"carotte","qty":2,"unit":"piece","note":"en rondelles"},{"id":"jaune-oeuf","qty":1,"unit":"piece"},{"id":"huile-olive","qty":50,"unit":"ml","note":"douce"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"cornichon","qty":40,"unit":"g","note":"hachés"},{"id":"capres","qty":1,"unit":"cas"},{"id":"curcuma","qty":1,"unit":"pincee"},{"id":"persil","qty":10,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"skyr","qty":250,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Mixez le cabillaud par impulsions avec 1 cac de sel jusqu'à une farce collante mais pas une purée. Ajoutez l'œuf, la farine, la crème, l'oignon râpé, l'aneth ciselé et la muscade. Mixez 10 secondes, puis laissez reposer 30 min au frais : la farce raffermit.","Rémoulade : fouettez le jaune avec la moutarde, puis l'huile en mince filet jusqu'à une mayonnaise ferme. Ajoutez cornichons, câpres, curcuma et un trait de citron.","Cuisez pommes de terre et carottes 18 min à la vapeur.","Formez des galettes ovales à l'aide d'une cuillère à soupe trempée dans le beurre fondu (environ 10 galettes).","Faites-les dorer dans le beurre à feu moyen 4 min par face : elles doivent gonfler, être bien dorées et fermes au centre.","Servez avec les pommes de terre et carottes parsemées de persil, la rémoulade et des quartiers de citron.","Prévoyez un skyr nature en dessert (son calcium limite l’absorption des oxalates)."],"tags":["familial","riche en protéines","une poêle","préparation à l’avance","lunch box"],"seasons":[],"technique":"poele","flavors":["herbace","iode","cremeux"],"tips":"Les galettes se mangent aussi froides sur du pain de seigle beurré, le lendemain."},{"id":"wld-hareng-pommes-de-terre-creme","name":"Hareng mariné, pommes de terre nouvelles et crème à la ciboulette","description":"L'assiette de la Saint-Jean suédoise : filets de hareng marinés, pommes de terre nouvelles chaudes à l'aneth, crème épaisse à la ciboulette, œufs durs et oignon rouge.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"nordique","prepTime":15,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"hareng","qty":300,"unit":"g","note":"filets marinés (matjes ou à l'oignon), égouttés"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"nouvelles"},{"id":"oeuf","qty":3,"unit":"piece"},{"id":"creme-fraiche","qty":100,"unit":"ml"},{"id":"ciboulette","qty":15,"unit":"g"},{"id":"aneth","qty":15,"unit":"g"},{"id":"oignon-rouge","qty":0.5,"unit":"piece","note":"en fines rondelles"},{"id":"beurre","qty":20,"unit":"g"},{"id":"pain-seigle","qty":2,"unit":"piece","note":"tranches beurrées","optional":true},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les pommes de terre nouvelles 18 à 20 min dans l'eau bouillante salée avec une branche d'aneth : elles doivent être tendres sous la pointe du couteau.","Pendant ce temps, cuisez les œufs 9 min dans l'eau bouillante, refroidissez-les à l'eau glacée et écalez-les.","Mélangez la crème avec la ciboulette ciselée, sel et poivre.","Coupez les filets de hareng en tronçons de 3 cm.","Égouttez les pommes de terre et roulez-les dans le beurre et l'aneth ciselé.","Dressez les pommes de terre chaudes, le hareng froid, les œufs coupés en deux, l'oignon rouge et la crème : le contraste chaud-froid fait tout le charme du plat."],"tags":["rapide","économique","riche en protéines","repas froid","fermenté"],"seasons":["printemps","ete"],"technique":"bouilli","flavors":["iode","acidule","lacte"],"tips":"Le hareng est l'un des poissons les plus riches en oméga-3 et en vitamine D, et l'un des moins chers."},{"id":"wld-pytt-i-panna","name":"Pytt i panna, poêlée suédoise au jaune d'œuf","description":"Dés de pommes de terre, de rôti de bœuf et de saucisse fumée rissolés au beurre avec oignon, servis avec un jaune d'œuf cru, betterave marinée et cornichons.","emoji":"🍳","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"nordique","prepTime":15,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"pomme-de-terre","qty":600,"unit":"g","note":"cuites la veille, en dés de 1 cm"},{"id":"boeuf-rosbif","qty":220,"unit":"g","note":"restes de rôti, en dés"},{"id":"saucisse-morteau","qty":160,"unit":"g","note":"ou falukorv / saucisse fumée, en dés"},{"id":"oignon","qty":2,"unit":"piece","note":"en petits dés"},{"id":"beurre","qty":30,"unit":"g"},{"id":"jaune-oeuf","qty":2,"unit":"piece","note":"très frais (ou 2 œufs au plat)"},{"id":"betterave","qty":120,"unit":"g","note":"cuite, marinée au vinaigre"},{"id":"cornichon","qty":40,"unit":"g"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"skyr","qty":250,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Faites fondre la moitié du beurre dans une grande poêle à feu moyen-vif. Mettez les dés de pommes de terre en une couche et laissez-les dorer 10 min en ne les retournant que 2 ou 3 fois : ils doivent être croustillants et dorés.","Dans une autre poêle, faites revenir l'oignon dans le reste du beurre 5 min à feu moyen jusqu'à ce qu'il soit doré, puis ajoutez saucisse et bœuf et faites-les rissoler 5 min.","Réunissez le tout, salez, poivrez, mélangez 2 min à feu vif.","Dressez en dôme dans les assiettes, creusez un puits et déposez un jaune d'œuf dans une demi-coquille.","Servez avec la betterave marinée en dés, les cornichons et le persil : chacun mélange le jaune dans la poêlée chaude.","Prévoyez un skyr nature en dessert (son calcium limite l’absorption des oxalates)."],"tags":["économique","une poêle","réconfortant","riche en protéines","calorique"],"seasons":["automne","hiver"],"technique":"poele","flavors":["reconfortant","umami","acidule"],"tips":"Le plat anti-gaspillage par excellence : il accepte aussi jambon, restes de porc ou d'agneau rôtis."},{"id":"wld-smorrebrod-crevettes-oeufs","name":"Smørrebrød en repas complet","description":"Trois tartines danoises sur pain de seigle beurré : crevettes et œufs durs à l'aneth, saumon fumé et crème au raifort-citron, radis et cresson. Un vrai déjeuner froid nourrissant.","emoji":"🥪","category":"salade-composee","mealTypes":["dejeuner"],"cuisine":"nordique","prepTime":25,"cookTime":10,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"pain-seigle","qty":6,"unit":"piece","note":"tranches de rugbrød"},{"id":"beurre","qty":30,"unit":"g","note":"mou"},{"id":"crevette","qty":250,"unit":"g","note":"cuites, décortiquées"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"saumon-fume","qty":150,"unit":"g"},{"id":"creme-fraiche","qty":80,"unit":"ml"},{"id":"moutarde","qty":1,"unit":"cac","note":"ou raifort râpé"},{"id":"citron","qty":1,"unit":"piece"},{"id":"aneth","qty":15,"unit":"g"},{"id":"concombre","qty":0.5,"unit":"piece","note":"en fines rondelles"},{"id":"radis","qty":80,"unit":"g","note":"en rondelles"},{"id":"mache","qty":40,"unit":"g","note":"cresson"},{"id":"oignon-rouge","qty":0.5,"unit":"piece","note":"en fines rondelles"},{"id":"capres","qty":1,"unit":"cas"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les œufs 9 min dans l'eau bouillante, refroidissez-les à l'eau glacée, écalez-les et tranchez-les.","Mélangez la crème fraîche avec la moutarde (ou le raifort), le zeste et un trait de citron, poivre.","Beurrez généreusement les tranches de seigle jusqu'aux bords : le beurre empêche le pain de détremper.","Tartines crevettes : rondelles de concombre, œufs tranchés, un tas de crevettes, aneth et quartier de citron.","Tartines saumon : une cuillère de crème, le saumon fumé en plis, oignon rouge, câpres et aneth.","Tartines fraîcheur : le reste de crème, radis, cresson et œuf. Servez les trois sortes en dégustation, avec couteau et fourchette."],"tags":["repas froid","riche en protéines","rapide","lunch box","week-end"],"seasons":["printemps","ete"],"technique":"sans-cuisson","flavors":["frais","iode","lacte"],"tips":"Au Danemark, on mange le smørrebrød dans l'ordre : hareng, puis poissons, puis viandes."},{"id":"wld-shepherds-pie","name":"Shepherd's pie à l'agneau","description":"Agneau haché mijoté avec carottes, céleri, petits pois et thym dans une sauce brune riche, recouvert d'une purée beurrée au cheddar gratinée au four.","emoji":"🥧","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"britannique","prepTime":30,"cookTime":60,"difficulty":"facile","servings":4,"ingredients":[{"id":"agneau-hache","qty":700,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece","note":"en petits dés"},{"id":"carotte","qty":2,"unit":"piece","note":"en petits dés"},{"id":"celeri-branche","qty":2,"unit":"piece","note":"en petits dés"},{"id":"petits-pois","qty":150,"unit":"g"},{"id":"concentre-tomate","qty":2,"unit":"cas"},{"id":"farine","qty":1,"unit":"cas"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"sauce-soja","qty":1,"unit":"cas","note":"ou sauce Worcestershire"},{"id":"anchois","qty":2,"unit":"piece","note":"écrasés (umami façon Worcestershire)"},{"id":"thym","qty":4,"unit":"brin"},{"id":"romarin","qty":1,"unit":"brin"},{"id":"pomme-de-terre-farineuse","qty":1100,"unit":"g"},{"id":"beurre","qty":50,"unit":"g"},{"id":"lait","qty":120,"unit":"ml"},{"id":"cheddar","qty":60,"unit":"g","note":"râpé"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une sauteuse à feu vif, faites dorer l'agneau haché 8 min en l'émiettant, sans matière grasse, jusqu'à ce qu'il soit bien bruni. Retirez l'excès de gras (gardez-en 1 cas).","Baissez à feu moyen, ajoutez oignon, carotte et céleri 6 min, puis concentré de tomate, anchois et farine 1 min.","Versez le bouillon et la sauce soja, ajoutez thym et romarin. Laissez mijoter 20 min à feu doux à découvert : la sauce doit être épaisse et napper la viande. Ajoutez les petits pois les 3 dernières minutes.","Pendant ce temps, cuisez les pommes de terre épluchées 20 min à l'eau salée, écrasez-les avec 40 g de beurre et le lait chaud. Salez, poivrez.","Préchauffez le four à 200 °C. Versez la viande dans un plat de 25 × 20 cm, couvrez de purée, tracez des sillons à la fourchette, parsemez de cheddar et du reste de beurre.","Enfournez 25 min, jusqu'à ce que le dessus soit doré et que la sauce bouillonne sur les bords. Laissez reposer 5 min avant de servir."],"tags":["four","familial","réconfortant","batch cooking","week-end"],"seasons":["automne","hiver"],"technique":"four","flavors":["reconfortant","umami","herbace"],"tips":"Avec du bœuf haché, il devient un cottage pie. Se congèle cuit en portions."},{"id":"wld-fish-pie","name":"Fish pie au haddock, cabillaud et crevettes","description":"Le gratin réconfortant britannique : cabillaud, haddock fumé, crevettes et œufs durs dans une béchamel au poireau et persil, sous une purée dorée au cheddar.","emoji":"🥧","category":"plat","mealTypes":["diner"],"cuisine":"britannique","prepTime":30,"cookTime":55,"difficulty":"facile","servings":4,"ingredients":[{"id":"cabillaud","qty":400,"unit":"g"},{"id":"haddock","qty":300,"unit":"g"},{"id":"crevette","qty":200,"unit":"g","note":"crues décortiquées"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"lait","qty":650,"unit":"ml"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"poireau","qty":1,"unit":"piece","note":"émincé"},{"id":"beurre","qty":80,"unit":"g"},{"id":"farine","qty":40,"unit":"g"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"persil","qty":20,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"pomme-de-terre-farineuse","qty":1100,"unit":"g"},{"id":"cheddar","qty":60,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pochez cabillaud et haddock dans 500 ml de lait avec le laurier, 6 min à frémissement. Égouttez le poisson en gardant le lait, effeuillez-le en gros morceaux. Cuisez les œufs 9 min, écalez-les et coupez-les en quatre.","Cuisez les pommes de terre épluchées 20 min à l'eau salée, écrasez-les avec 30 g de beurre et 150 ml de lait chaud.","Faites suer le poireau 5 min dans 40 g de beurre à feu moyen, ajoutez la farine 1 min, puis versez le lait de pochage en fouettant. Laissez épaissir 4 min : la béchamel doit napper la cuillère. Ajoutez moutarde, persil, muscade, sel et poivre.","Préchauffez le four à 200 °C. Répartissez poisson, crevettes crues et œufs dans un plat de 25 × 20 cm, nappez de béchamel.","Couvrez de purée à la poche ou à la cuillère, parsemez de cheddar et du reste de beurre en noisettes.","Enfournez 30 min jusqu'à ce que le dessus soit doré et que la sauce bouillonne sur les bords ; les crevettes finissent de cuire dans le four. Laissez reposer 5 min."],"tags":["four","familial","réconfortant","riche en protéines","week-end"],"seasons":["automne","hiver"],"technique":"four","flavors":["cremeux","iode","fume"],"tips":"Préparez-le jusqu'à l'étape 5 la veille : comptez alors 40 min de four."},{"id":"wld-steak-kidney-pie","name":"Steak and kidney pie","description":"La tourte britannique : paleron et rognons de veau braisés à la bière brune avec oignons et champignons, sous une pâte brisée au beurre bien dorée, servie avec petits pois.","emoji":"🥧","category":"mijote","mealTypes":["diner"],"cuisine":"britannique","prepTime":40,"cookTime":165,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"boeuf-paleron","qty":650,"unit":"g","note":"en cubes de 3 cm"},{"id":"rognon","qty":300,"unit":"g","note":"veau ou agneau, parés, en morceaux"},{"id":"farine","qty":240,"unit":"g","note":"30 g pour la viande, 210 g pour la pâte"},{"id":"beurre","qty":120,"unit":"g","note":"100 g froid pour la pâte"},{"id":"oignon","qty":2,"unit":"piece","note":"émincés"},{"id":"champignon","qty":200,"unit":"g","note":"en quartiers"},{"id":"biere","qty":330,"unit":"ml","note":"bière brune (stout)"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"sauce-soja","qty":1,"unit":"cas","note":"ou sauce Worcestershire"},{"id":"thym","qty":4,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"oeuf","qty":1,"unit":"piece","note":"pour la dorure"},{"id":"petits-pois","qty":400,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pâte : sablez 210 g de farine, 100 g de beurre froid en dés et 1/2 cac de sel du bout des doigts, ajoutez 4 à 5 cas d'eau glacée et rassemblez en boule sans pétrir. Filmez, 1 h au frais.","Retirez les nerfs et le gras blanc des rognons, coupez-les en morceaux de 2 cm, faites-les tremper 15 min dans de l'eau froide salée, rincez et séchez.","Roulez paleron et rognons dans 30 g de farine salée et poivrée. Dans une cocotte, faites-les dorer en 3 fournées dans 20 g de beurre à feu vif, 3 min chacune. Réservez.","Faites fondre les oignons 6 min à feu moyen, ajoutez les champignons 4 min, puis remettez la viande, la bière, le bouillon, la sauce soja, thym et laurier. Portez à frémissement, couvrez et laissez braiser 1 h 45 à feu très doux : le bœuf doit être tendre et la sauce épaisse. Laissez tiédir.","Préchauffez le four à 200 °C. Versez la garniture dans un plat à tourte de 22 cm, abaissez la pâte sur 4 mm, couvrez le plat, soudez les bords et pratiquez une cheminée au centre. Dorez à l'œuf battu.","Enfournez 35 à 40 min jusqu'à ce que la pâte soit dorée et croustillante. Servez avec les petits pois cuits 5 min à l'eau bouillante et roulés dans une noix de beurre."],"tags":["abats","week-end","mijoté","réconfortant","calorique","four"],"seasons":["automne","hiver"],"technique":"braise","flavors":["umami","reconfortant"],"tips":"Les rognons d'agneau, plus doux, sont parfaits pour une première fois. La garniture se prépare 2 jours à l'avance."},{"id":"wld-goulasch-jarret","name":"Goulasch hongrois de jarret au paprika","description":"Pörkölt de jarret de bœuf fondant mijoté longuement avec beaucoup d'oignons, paprika doux et fumé, carvi, poivron et tomate, avec les pommes de terre cuites dans la sauce.","emoji":"🍲","category":"mijote","mealTypes":["diner","dejeuner"],"cuisine":"europe-centrale","prepTime":25,"cookTime":170,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-jarret","qty":1000,"unit":"g","note":"en cubes de 4 cm"},{"id":"oignon","qty":3,"unit":"piece","note":"émincés"},{"id":"graisse-canard","qty":3,"unit":"cas","note":"saindoux"},{"id":"paprika","qty":3,"unit":"cas","note":"dont 1 de paprika fumé"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"graines de carvi"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"poivron-rouge","qty":2,"unit":"piece","note":"en lanières"},{"id":"tomate","qty":2,"unit":"piece","note":"en dés"},{"id":"bouillon-boeuf","qty":600,"unit":"ml"},{"id":"pomme-de-terre","qty":900,"unit":"g","note":"en gros cubes"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"origan","qty":1,"unit":"cac","note":"marjolaine"},{"id":"creme-fraiche","qty":80,"unit":"ml","optional":true},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Dans une cocotte en fonte, faites fondre les oignons dans le saindoux à feu moyen-doux 15 min en remuant : ils doivent être dorés et confits, c'est la base de la sauce.","Montez à feu vif, ajoutez la viande salée et faites-la colorer 5 min sur toutes les faces.","Retirez la cocotte du feu, ajoutez paprika, carvi et ail écrasé, mélangez 30 secondes (le paprika brûle vite et devient amer).","Remettez sur le feu, ajoutez concentré de tomate, poivrons, tomates, laurier, marjolaine et le bouillon. Portez à frémissement, couvrez et laissez mijoter 2 h à feu très doux.","Ajoutez les pommes de terre et poursuivez 30 à 35 min à découvert : elles doivent être tendres et la sauce épaisse, rouge sombre, et le jarret se défaire à la cuillère.","Rectifiez l'assaisonnement, servez en assiettes creuses avec une cuillerée de crème fraîche."],"tags":["mijoté","week-end","batch cooking","riche en collagène","réconfortant","sans gluten"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["epice","reconfortant","fume"],"tips":"Le jarret, riche en collagène, donne une sauce naturellement nappante. Encore meilleur le lendemain."},{"id":"wld-schnitzel-viennois","name":"Wiener Schnitzel et salade de pommes de terre viennoise","description":"Escalopes de veau aplaties, panées et dorées au beurre clarifié jusqu'à ce que la panure souffle, avec la salade de pommes de terre tiède au bouillon et vinaigre, et une salade verte.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"europe-centrale","prepTime":25,"cookTime":25,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"veau-escalope","qty":3,"unit":"piece","note":"fines, dans la noix"},{"id":"farine","qty":30,"unit":"g"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"panure","qty":60,"unit":"g","note":"chapelure fine de pain blanc"},{"id":"beurre-clarifie","qty":3,"unit":"cas"},{"id":"citron","qty":1,"unit":"piece"},{"id":"pomme-de-terre","qty":500,"unit":"g","note":"à chair ferme"},{"id":"bouillon-volaille","qty":120,"unit":"ml","note":"chaud"},{"id":"vinaigre-cidre","qty":3,"unit":"cas","note":"vinaigre de vin blanc"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"oignon","qty":0.5,"unit":"piece","note":"très finement haché"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"ciboulette","qty":10,"unit":"g"},{"id":"laitue","qty":100,"unit":"g","note":"feuilles tendres"},{"id":"persil","qty":5,"unit":"g","optional":true},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Salade : cuisez les pommes de terre entières 20 min à l'eau salée, pelez-les chaudes et tranchez-les en rondelles de 4 mm. Arrosez-les aussitôt du bouillon chaud mélangé au vinaigre, à la moutarde, à l'oignon et au sel. Laissez absorber 15 min, puis ajoutez huile d'olive et ciboulette : la salade doit être crémeuse et luisante.","Placez les escalopes entre deux feuilles de papier cuisson et aplatissez-les au rouleau à 4 mm d'épaisseur. Salez.","Passez-les dans la farine (tapotez), dans les œufs battus, puis posez-les sur la chapelure sans presser : la panure doit rester lâche pour gonfler.","Chauffez le beurre clarifié sur 5 mm dans une grande poêle à feu moyen-vif (170 °C : une miette grésille immédiatement). Cuisez les escalopes une à une 2 min par face en secouant la poêle et en les arrosant de beurre : la panure doit onduler, se décoller et être dorée.","Égouttez sur du papier absorbant. Servez aussitôt avec un quartier de citron, la salade de pommes de terre et la laitue assaisonnée d'un filet de vinaigrette."],"tags":["riche en protéines","familial","calorique","week-end","prise de masse"],"seasons":[],"technique":"friture-legere","flavors":["reconfortant","acidule"],"tips":"Le secret de la panure soufflée : ne pas la tasser et secouer constamment la poêle pour que le beurre passe dessus."},{"id":"wld-foie-veau-berlinoise","name":"Foie de veau à la berlinoise, pommes et oignons","description":"Tranches de foie de veau rapidement saisies au beurre, avec rondelles de pomme caramélisées et oignons fondants, sur une purée de pommes de terre au lait et à la muscade.","emoji":"🍎","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"europe-centrale","prepTime":15,"cookTime":25,"difficulty":"facile","servings":2,"ingredients":[{"id":"foie-veau","qty":2.25,"unit":"piece","note":"tranches de 1 cm"},{"id":"pomme","qty":2,"unit":"piece","note":"acidulées, en rondelles de 1 cm"},{"id":"oignon","qty":2,"unit":"piece","note":"en rondelles"},{"id":"beurre","qty":50,"unit":"g"},{"id":"farine","qty":2,"unit":"cas"},{"id":"pomme-de-terre-farineuse","qty":700,"unit":"g"},{"id":"lait","qty":150,"unit":"ml"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"origan","qty":0.5,"unit":"cac","note":"marjolaine"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"comte","qty":40,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Cuisez les pommes de terre épluchées en morceaux 20 min à l'eau salée. Égouttez, écrasez avec 15 g de beurre, le lait chaud et la muscade.","Pendant ce temps, faites fondre les oignons dans 15 g de beurre à feu moyen-doux 15 min avec une pincée de sel, jusqu'à ce qu'ils soient dorés et fondants. Réservez au chaud.","Dans la même poêle, faites dorer les rondelles de pomme dans 10 g de beurre 2 min par face : elles doivent être caramélisées mais encore se tenir. Réservez avec les oignons.","Épongez le foie, passez-le dans la farine et tapotez. Faites mousser le reste de beurre à feu moyen-vif et saisissez le foie 1 min 30 par face : il doit rester rosé à cœur. Salez et poivrez seulement après cuisson (le sel le durcit).","Servez le foie sur la purée, couvert d'oignons et de pommes, arrosé du beurre de cuisson, parsemé de persil et de marjolaine.","Terminez le repas par un morceau de fromage affiné (comté, emmental) (son calcium limite l’absorption des oxalates)."],"tags":["abats","rapide","riche en protéines","réconfortant","économique"],"seasons":["automne","hiver"],"technique":"poele","flavors":["fruite","reconfortant","lacte"],"tips":"Le foie de génisse, moins cher, convient aussi. Comptez 1 min de moins par face pour des tranches de 7 mm."}]`);export{e as default};